'use client';

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { 
  Users, 
  Eye, 
  Clock, 
  ArrowUpRight, 
  ArrowDownRight, 
  MousePointerClick, 
  Globe, 
  Smartphone, 
  Monitor, 
  Tablet, 
  Search, 
  Share2, 
  Compass, 
  TrendingUp,
  MapPin
} from 'lucide-react';
import { Button } from "@/components/ui/button";

interface TrafficProps {
  stats: {
    pageViews: number;
    uniqueVisitors: number;
    avgTimeOnPage: string;
    bounceRate: string;
    topPages: { path: string; views: number; change: string }[];
    sources: { source: string; visitors: number; percentage: number }[];
    devices: { device: string; percentage: number; icon: string }[];
    geo: { country: string; visitors: number; flag: string }[];
  };
}

export default function TrafficClient({ stats }: TrafficProps) {
  const [timeRange, setTimeRange] = useState<'24h' | '7d' | '30d' | 'all'>('7d');

  return (
    <div className="space-y-6">
      {/* Header and Controls */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-white flex items-center gap-2">
            <TrendingUp className="h-8 w-8 text-emerald-400" />
            Trafikanalys
          </h1>
          <p className="text-slate-400 mt-1">
            Realtidsstatistik och besöksmönster på Spelautomater.se
          </p>
        </div>
        <div className="flex items-center gap-2 bg-slate-900 border border-slate-800 p-1 rounded-xl">
          {(['24h', '7d', '30d', 'all'] as const).map((range) => (
            <Button
              key={range}
              variant={timeRange === range ? "default" : "ghost"}
              size="sm"
              onClick={() => setTimeRange(range)}
              className={timeRange === range ? "bg-emerald-600 hover:bg-emerald-500 text-white" : "text-slate-400 hover:text-white"}
            >
              {range === '24h' ? '24 timmar' : range === '7d' ? '7 dagar' : range === '30d' ? '30 dagar' : 'Allt'}
            </Button>
          ))}
        </div>
      </div>

      {/* Main Metric Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium text-slate-400">Sidvisningar</CardTitle>
            <div className="p-2 bg-emerald-500/10 rounded-lg text-emerald-400">
              <Eye className="h-5 w-5" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">{stats.pageViews.toLocaleString('sv-SE')}</div>
            <div className="flex items-center text-xs text-emerald-400 mt-1">
              <ArrowUpRight className="h-4 w-4 mr-1" />
              <span>+12.4% jämfört med föregående period</span>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium text-slate-400">Unika besökare</CardTitle>
            <div className="p-2 bg-blue-500/10 rounded-lg text-blue-400">
              <Users className="h-5 w-5" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">{stats.uniqueVisitors.toLocaleString('sv-SE')}</div>
            <div className="flex items-center text-xs text-emerald-400 mt-1">
              <ArrowUpRight className="h-4 w-4 mr-1" />
              <span>+8.2% jämfört med föregående period</span>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium text-slate-400">Genomsnittlig tid</CardTitle>
            <div className="p-2 bg-purple-500/10 rounded-lg text-purple-400">
              <Clock className="h-5 w-5" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">{stats.avgTimeOnPage}</div>
            <div className="flex items-center text-xs text-emerald-400 mt-1">
              <ArrowUpRight className="h-4 w-4 mr-1" />
              <span>+14s ökad retention</span>
            </div>
          </CardContent>
        </Card>

        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader className="flex flex-row items-center justify-between pb-2">
            <CardTitle className="text-sm font-medium text-slate-400">Avvisningsfrekvens</CardTitle>
            <div className="p-2 bg-amber-500/10 rounded-lg text-amber-400">
              <MousePointerClick className="h-5 w-5" />
            </div>
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-white">{stats.bounceRate}</div>
            <div className="flex items-center text-xs text-emerald-400 mt-1">
              <ArrowDownRight className="h-4 w-4 mr-1" />
              <span>-2.1% (bättre engagemang)</span>
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Most visited pages */}
        <Card className="lg:col-span-2 bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-white">Mest besökta sidor</CardTitle>
            <CardDescription className="text-slate-400">Vilka sidor driver mest intresse och engagemang?</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats.topPages.map((page, idx) => (
                <div key={idx} className="flex items-center justify-between p-3 bg-slate-950/40 rounded-xl border border-slate-800/60 hover:border-slate-700 transition-colors">
                  <div className="flex items-center gap-3 overflow-hidden">
                    <span className="text-xs font-mono px-2 py-1 bg-slate-800 rounded text-slate-400">#{idx + 1}</span>
                    <span className="text-sm text-slate-200 font-medium truncate">{page.path}</span>
                  </div>
                  <div className="flex items-center gap-4">
                    <span className="text-sm font-semibold text-white">{page.views.toLocaleString('sv-SE')}</span>
                    <span className={`text-xs px-2 py-0.5 rounded-full ${
                      page.change.startsWith('+') ? 'bg-emerald-500/10 text-emerald-400' : 'bg-red-500/10 text-red-400'
                    }`}>
                      {page.change}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Traffic Sources */}
        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-white flex items-center gap-2">
              <Compass className="h-5 w-5 text-blue-400" />
              Trafikkällor
            </CardTitle>
            <CardDescription className="text-slate-400">Varifrån kommer besökarna?</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats.sources.map((source, idx) => (
                <div key={idx} className="space-y-1.5">
                  <div className="flex justify-between text-sm">
                    <span className="text-slate-300 font-medium">{source.source}</span>
                    <span className="text-slate-400">{source.percentage}%</span>
                  </div>
                  <div className="w-full bg-slate-800 rounded-full h-2">
                    <div 
                      className="bg-blue-500 h-2 rounded-full" 
                      style={{ width: `${source.percentage}%` }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Device breakdown */}
        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-white flex items-center gap-2">
              <Smartphone className="h-5 w-5 text-emerald-400" />
              Enheter & Plattformer
            </CardTitle>
            <CardDescription className="text-slate-400">Fördelning mellan mobilt och desktop</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-4">
              {stats.devices.map((dev, idx) => (
                <div key={idx} className="bg-slate-950/40 p-4 rounded-xl border border-slate-800/60 text-center">
                  <div className="flex justify-center mb-2">
                    {dev.device === 'Mobil' && <Smartphone className="h-6 w-6 text-emerald-400" />}
                    {dev.device === 'Dator' && <Monitor className="h-6 w-6 text-blue-400" />}
                    {dev.device === 'Surfplatta' && <Tablet className="h-6 w-6 text-purple-400" />}
                  </div>
                  <div className="text-xl font-bold text-white">{dev.percentage}%</div>
                  <div className="text-xs text-slate-400 mt-1">{dev.device}</div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Geographics */}
        <Card className="bg-slate-900/50 border-slate-800 backdrop-blur-sm">
          <CardHeader>
            <CardTitle className="text-lg font-semibold text-white flex items-center gap-2">
              <Globe className="h-5 w-5 text-cyan-400" />
              Geografi
            </CardTitle>
            <CardDescription className="text-slate-400">Besökare per land</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.geo.map((item, idx) => (
                <div key={idx} className="flex items-center justify-between p-2.5 bg-slate-950/40 rounded-lg border border-slate-800/40">
                  <div className="flex items-center gap-3">
                    <span className="text-lg">{item.flag}</span>
                    <span className="text-sm font-medium text-slate-200">{item.country}</span>
                  </div>
                  <span className="text-sm font-mono text-slate-400">{item.visitors.toLocaleString('sv-SE')}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}
