export const metadata: Metadata = {
  title: 'Hantera Bonusar | Admin | Spelautomater.se',
  description: 'Översikt och hantering av casinobonusar.',
};

export const dynamic = 'force-dynamic';

export default async function AdminBonusesPage() {
  const [bonuses, casinos] = await Promise.all([
    prisma.bonus.findMany({
      orderBy: { updatedAt: 'desc' },
      include: {
        casino: {
          select: {
            id: true,
            name: true,
            logoUrl: true,
            rating: true,
          },
        },
      },
    }),
    prisma.casino.findMany({
      select: {
        id: true,
        name: true,
      },
      orderBy: { name: 'asc' },
    }),
  ]);

  return (
    <div className="space-y-6">
