      b.name.toLowerCase().includes(search.toLowerCase()) ||
      b.casino.name.toLowerCase().includes(search.toLowerCase()) ||
      (b.promoCode && b.promoCode.toLowerCase().includes(search.toLowerCase()));

    const matchesType = typeFilter === 'ALL' || b.type === typeFilter;
    const matchesActive = activeFilter === 'ALL' || 
      (activeFilter === 'ACTIVE' ? b.isActive : !b.isActive);
    const matchesCasino = casinoFilter === 'ALL' || b.casino.id === casinoFilter;

    return matchesSearch && matchesType && matchesActive && matchesCasino;
  });

  const toggleStatus = async (id: string, currentStatus: boolean) => {
    try {
      const res = await fetch(`/api/admin/bonuses/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: !currentStatus }),
      });
      if (res.ok) {
        setBonuses((prev) =>
          prev.map((item) =>
            item.id === id ? { ...item, isActive: !currentStatus } : item
          )
        );
      }
    } catch (e) {
      console.error('Failed to update status', e);
    }
  };

  const deleteBonus = async (id: string) => {
    if (!confirm('Är du säker på att du vill ta bort denna bonus?')) return;
    try {
      const res = await fetch(`/api/admin/bonuses/${id}`, {
        method: 'DELETE',
      });
      if (res.ok) {
        setBonuses((prev) => prev.filter((item) => item.id !== id));
      }
    } catch (e) {
      console.error('Failed to delete bonus', e);
    }
  };

  return (
    <div className="space-y-6">
      {/* Controls Bar */}
      <div className="flex flex-col md:flex-row gap-4 justify-between items-stretch md:items-center">
        <div className="flex flex-1 gap-3 items-center">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
            <Input
              type="text"
              placeholder="Sök bonus, casino eller kod..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 bg-slate-900 border-slate-800 text-slate-200 focus:border-emerald-500 rounded-xl"
            />
          </div>

          <select
            value={typeFilter}
            onChange={(e) => setTypeFilter(e.target.value)}
            className="bg-slate-900 border border-slate-800 text-slate-300 text-sm rounded-xl px-3 py-2 focus:outline-none focus:border-emerald-500"
          >
            <option value="ALL">Alla typer</option>
            <option value="DEPOSIT_MATCH">Insättningsbonus</option>
            <option value="FREE_SPINS">Free Spins</option>
            <option value="NO_DEPOSIT">Utan insättning</option>
            <option value="CASHBACK">Cashback</option>
            <option value="COMBO">Kombobonus</option>
          </select>

          <select
            value={casinoFilter}
            onChange={(e) => setCasinoFilter(e.target.value)}
            className="bg-slate-900 border border-slate-800 text-slate-300 text-sm rounded-xl px-3 py-2 focus:outline-none focus:border-emerald-500 max-w-[200px]"
          >
            <option value="ALL">Alla casinon</option>
            {casinos.map((c) => (
              <option key={c.id} value={c.id}>{c.name}</option>
            ))}
          </select>

          <select
            value={activeFilter}
            onChange={(e) => setActiveFilter(e.target.value)}
            className="bg-slate-900 border border-slate-800 text-slate-300 text-sm rounded-xl px-3 py-2 focus:outline-none focus:border-emerald-500"
          >
            <option value="ALL">Alla statusar</option>
            <option value="ACTIVE">Aktiva</option>
            <option value="INACTIVE">Inaktiva</option>
          </select>
        </div>

        <Button asChild className="bg-emerald-600 hover:bg-emerald-500 text-white font-medium rounded-xl">
          <Link href="/admin/bonuses/new">
            <Plus className="h-4 w-4 mr-2" />
            Lägg till bonus
          </Link>
        </Button>
      </div>

      {/* Bonuses Table */}
      <div className="bg-slate-900/60 border border-slate-800/80 rounded-2xl overflow-hidden shadow-sm backdrop-blur-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-slate-300">
            <thead className="bg-slate-800/50 text-xs uppercase text-slate-400 font-semibold border-b border-slate-800">
              <tr>
                <th className="px-6 py-4">Casino & Bonus</th>
                <th className="px-6 py-4">Typ & Värde</th>
                <th className="px-6 py-4">Omsättningskrav</th>
                <th className="px-6 py-4">Min. Insättning</th>
                <th className="px-6 py-4 text-center">Status</th>
                <th className="px-6 py-4 text-right">Åtgärder</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/60">
              {filteredBonuses.length === 0 ? (
                <tr>
                  <td colSpan={6} className="text-center py-12 text-slate-500">
                    Inga bonusar matchade din sökning.
                  </td>
                </tr>
              ) : (
                filteredBonuses.map((bonus) => (
                  <tr key={bonus.id} className="hover:bg-slate-800/20 transition-colors">
                    {/* Casino & Bonus Name */}
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-xl bg-slate-800 border border-slate-700/50 flex items-center justify-center overflow-hidden flex-shrink-0">
                          {bonus.casino.logoUrl ? (
                            <img src={bonus.casino.logoUrl} alt={bonus.casino.name} className="w-full h-full object-cover" />
                          ) : (
                            <Gift className="h-5 w-5 text-emerald-400" />
                          )}
                        </div>
                        <div className="flex flex-col min-w-0">
                          <span className="text-xs font-semibold text-emerald-400 truncate">
                            {bonus.casino.name}
                          </span>
                          <span className="text-base font-semibold text-white truncate">
                            {bonus.name}
                          </span>
                          {bonus.promoCode && (
                            <span className="text-xs font-mono bg-slate-800 text-amber-300 px-1.5 py-0.5 rounded w-fit mt-0.5 border border-amber-500/20">
                              KOD: {bonus.promoCode}
                            </span>
                          )}
                        </div>
                      </div>
                    </td>

                    {/* Type & Value */}
                    <td className="px-6 py-4">
                      <div className="space-y-1">
                        <div className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                          {bonus.type}
                        </div>
                        <div className="text-sm font-medium text-slate-200">
                          {bonus.amount || (bonus.percentage ? `${bonus.percentage}%` : '')}
                          {bonus.spins ? ` + ${bonus.spins} spins` : ''}
                        </div>
                      </div>
                    </td>

                    {/* Wagering */}
                    <td className="px-6 py-4">
                      <div className="text-slate-300 font-medium">
                        {bonus.wagering ? `${bonus.wagering}` : 'Omsättningsfri'}
                      </div>
                      <div className="text-xs text-slate-500">
                        {bonus.isSticky ? 'Sticky bonus' : 'No-sticky'}
                      </div>
                    </td>

                    {/* Min Deposit */}
                    <td className="px-6 py-4">
                      <div className="text-slate-300">
                        {bonus.minDeposit ? `${bonus.minDeposit} kr` : 'Ingen gräns'}
                      </div>
                    </td>

                    {/* Status Toggle */}
                    <td className="px-6 py-4 text-center">
                      <button
                        onClick={() => toggleStatus(bonus.id, bonus.isActive)}
                        className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium transition-colors ${
                          bonus.isActive
                            ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 hover:bg-emerald-500/20'
                            : 'bg-rose-500/10 text-rose-400 border border-rose-500/20 hover:bg-rose-500/20'
                        }`}
                      >
                        {bonus.isActive ? (
                          <>
                            <CheckCircle2 className="h-3.5 w-3.5" />
                            Aktiv
                          </>
                        ) : (
                          <>
                            <XCircle className="h-3.5 w-3.5" />
                            Inaktiv
                          </>
                        )}
                      </button>
                    </td>

                    {/* Actions */}
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="icon"
                          asChild
                          className="h-8 w-8 text-slate-400 hover:text-white hover:bg-slate-800"
                        >
                          <Link href={`/admin/bonuses/${bonus.id}`}>
                            <Edit className="h-4 w-4" />
                          </Link>
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => deleteBonus(bonus.id)}
                          className="h-8 w-8 text-slate-400 hover:text-rose-400 hover:bg-rose-500/10"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
