'use client';

import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { 
  Gift, 
  Save, 
  ArrowLeft, 
  Trash2, 
  Coins, 
  Percent, 
  ShieldCheck, 
  Check, 
  AlertCircle 
} from 'lucide-react';
import Link from 'next/link';

interface BonusFormProps {
  initialData?: any;
  casinos: { id: string; name: string }[];
}

export default function BonusForm({ initialData, casinos }: BonusFormProps) {
  const router = useRouter();
  const isEditing = !!initialData;

  const [formData, setFormData] = useState({
    name: initialData?.name || '',
    casinoId: initialData?.casinoId || (casinos[0]?.id || ''),
    type: initialData?.type || 'DEPOSIT_MATCH',
    amount: initialData?.amount || '',
    percentage: initialData?.percentage || '',
    spins: initialData?.spins || '',
    minDeposit: initialData?.minDeposit || '100',
    wagering: initialData?.wagering || '20x',
    maxBet: initialData?.maxBet || '',
    validDays: initialData?.validDays || '60',
    isSticky: initialData?.isSticky ?? false,
    isActive: initialData?.isActive ?? true,
    promoCode: initialData?.promoCode || '',
    affiliateUrl: initialData?.affiliateUrl || '',
    terms: initialData?.terms || '',
    description: initialData?.description || '',
    features: initialData?.features ? (Array.isArray(initialData.features) ? initialData.features.join('\n') : initialData.features) : '',
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const payload = {
        ...formData,
        percentage: formData.percentage ? parseInt(formData.percentage) : null,
        spins: formData.spins ? parseInt(formData.spins) : null,
        minDeposit: formData.minDeposit ? parseFloat(formData.minDeposit) : null,
        validDays: formData.validDays ? parseInt(formData.validDays) : null,
        features: formData.features.split('\n').map((f: string) => f.trim()).filter(Boolean),
      };

      const url = isEditing ? `/api/admin/bonuses/${initialData.id}` : '/api/admin/bonuses';
      const method = isEditing ? 'PUT' : 'POST';

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.message || 'Ett fel uppstod vid sparandet.');
      }

      router.push('/admin/bonuses');
      router.refresh();
    } catch (err: any) {
      setError(err.message || 'Ett fel inträffade.');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async () => {
    if (!confirm('Är du säker på att du vill radera denna bonus?')) return;
    setLoading(true);
    try {
      const res = await fetch(`/api/admin/bonuses/${initialData.id}`, {
        method: 'DELETE',
      });
      if (res.ok) {
        router.push('/admin/bonuses');
        router.refresh();
      }
    } catch (err) {
      console.error(err);
      setError('Kunde inte radera bonusen.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-8 max-w-4xl">
      {error && (
        <div className="p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl flex items-center gap-3">
          <AlertCircle className="h-5 w-5 flex-shrink-0" />
          <p className="text-sm">{error}</p>
        </div>
      )}

      {/* Basic info */}
      <Card className="bg-slate-900 border-slate-800">
        <CardHeader>
          <CardTitle className="text-lg text-white font-semibold">Grundläggande information</CardTitle>
          <CardDescription className="text-slate-400">Ange tillhörande casino och bonustyp</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Kopplat Casino *</label>
              <select
                required
                value={formData.casinoId}
                onChange={(e) => setFormData({ ...formData, casinoId: e.target.value })}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-slate-200 text-sm focus:outline-none focus:border-emerald-500"
              >
                <option value="" disabled>Välj casino...</option>
                {casinos.map((c) => (
                  <option key={c.id} value={c.id}>{c.name}</option>
                ))}
              </select>
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Bonustyp *</label>
              <select
                required
                value={formData.type}
                onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2.5 text-slate-200 text-sm focus:outline-none focus:border-emerald-500"
              >
                <option value="DEPOSIT_MATCH">Insättningsbonus (Matchning)</option>
                <option value="FREE_SPINS">Free Spins</option>
                <option value="NO_DEPOSIT">Utan insättning</option>
                <option value="CASHBACK">Cashback</option>
                <option value="COMBO">Kombobonus (Match + Spins)</option>
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-200">Bonusens Namn/Rubrik *</label>
            <Input
              required
              placeholder="t.ex. 100% upp till 2000 kr + 100 free spins"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="bg-slate-950 border-slate-800 text-slate-200"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-slate-200">Beskrivning</label>
            <Textarea
              rows={3}
              placeholder="Kort beskrivande text om bonusen..."
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              className="bg-slate-950 border-slate-800 text-slate-200 resize-none"
            />
          </div>
        </CardContent>
      </Card>

      {/* Bonus Value & Limits */}
      <Card className="bg-slate-900 border-slate-800">
        <CardHeader>
          <CardTitle className="text-lg text-white font-semibold">Bonusvärde & Villkor</CardTitle>
          <CardDescription className="text-slate-400">Konfigurera belopp, omsättning och giltighetstid</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Maxbelopp (text)</label>
              <Input
                placeholder="t.ex. 2000 kr"
                value={formData.amount}
                onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                className="bg-slate-950 border-slate-800 text-slate-200"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Procent (%)</label>
              <Input
                type="number"
                placeholder="100"
                value={formData.percentage}
                onChange={(e) => setFormData({ ...formData, percentage: e.target.value })}
                className="bg-slate-950 border-slate-800 text-slate-200"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Antal Free Spins</label>
              <Input
                type="number"
                placeholder="100"
                value={formData.spins}
                onChange={(e) => setFormData({ ...formData, spins: e.target.value })}
                className="bg-slate-950 border-slate-800 text-slate-200"
              />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Omsättningskrav</label>
              <Input
                placeholder="t.ex. 20x (B+D) eller 0x"
                value={formData.wagering}
                onChange={(e) => setFormData({ ...formData, wagering: e.target.value })}
                className="bg-slate-950 border-slate-800 text-slate-200"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Min. Insättning (kr)</label>
              <Input
                type="number"
                placeholder="100"
                value={formData.minDeposit}
                onChange={(e) => setFormData({ ...formData, minDeposit: e.target.value })}
                className="bg-slate-950 border-slate-800 text-slate-200"
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-slate-200">Giltighetstid (dagar)</label>
              <Input
                type="number"
